mapper.select:
SELECT a.*, pro.type_id, b.`name`, b.product_type, b.type FROM mes_building_product_process pro left join mes_building_product_process_link a on pro.id = a.product_process_id LEFT JOIN mes_building_process b ON a.process_id = b.id WHERE product_process_id in ( SELECT id FROM mes_building_product_process WHERE bool_delete_enum = 0
and type_id = #{id}
and product_type=#{productType} AND bool_delete_enum = 0 ) AND a.bool_delete_enum =0 ORDER BY a.sequence

select link.*, wk.name 'shopName', line.name 'lineName', pro.name 'processName', ul.user_name 'teamLeaderName' from mes_building_product_process pp left join mes_building_product_process_link link on pp.id = link.product_process_id and pp.type_id = #{classId} left join mes_building_process pro on link.process_id = pro.id and pro.bool_delete_enum = 0 left join mes_building_team_user_link ul on link.team_id = ul.team_id and ul.bool_leader_enum = 1 and ul.bool_delete_enum = 0 left join mes_building_workshop wk on pp.workshop_id = wk.id and wk.bool_delete_enum = 0 left join mes_building_production_line line on pp.production_line_id = line.id and line.bool_delete_enum = 0 where link.bool_delete_enum = 0 and pp.bool_history = 0
and pp.production_line_id = #{prodLineId}
and pp.product_type = #{taskTypeEnum}
